	\coordinate (H) at ($\k*(1,\tanb)+(A)$);
	\coordinate (J) at ($(\l*\cos,0)+\l*\tan/2*(1,\tanb)$);
	\draw[Stealth-Stealth] (0,0) node[below left]{C} -- ++(30:5) node[above]{E};
	\draw[Stealth-Stealth] (30:\l) -- ++(-90:5) node[below]{G};
